{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine, a lipophilic fused-ring drug with extensive first-pass metabolism, had absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold; its high transfer score and direct human F measurement support a low-F phenotype for the similarly lipophilic, metabolically labile steroid-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Ursodeoxycholic acid, a steroid, showed 50% systemic availability in healthy subjects, above the threshold; however, its carboxyl and hydroxyl groups and enterohepatic circulation make it less transferable to the neutral diketone query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ethinylestradiol, a steroid with a 17α-ethinyl group protecting against metabolism, had about 43% oral bioavailability; the protective group is absent in the query, limiting transferability of this high-F result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low because the highest-transfer direct human F evidence (pentazocine, 18%) supports F<20%, and the query's unmodified steroid diketone is prone to first-pass metabolism; high-F steroid analogues are less transferable due to protective groups or enterohepatic circulation.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability study for the query molecule in humans.",
    "First-pass metabolism of the 3,17-diketone is not experimentally quantified.",
    "Solubility-limited absorption is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

